const b = $input.first().json.body || {};
const s = (v) => String(v ?? '').trim();
// Une seule ligne : empeche d'injecter des lignes dans l'objet ou le recapitulatif.
const ligne = (v) => s(v).replace(/[\r\n\t]+/g, ' ');
const nom = ligne(b.nom), prenom = ligne(b.prenom), telephone = ligne(b.telephone), email = ligne(b.email), message = s(b.message);
const erreurs = [];
if (!nom || nom.length > 80) erreurs.push('nom');
if (!prenom || prenom.length > 80) erreurs.push('prenom');
if (!/^0\d{9}$/.test(telephone.replace(/[\s.\-]/g, ''))) erreurs.push('telephone');
if (email.length > 254 || !/^[^\s@,;<>]+@[^\s@,;<>]+\.[^\s@,;<>]{2,}$/.test(email)) erreurs.push('email');
if (!message || message.length > 2000) erreurs.push('message');
if (b.consentement !== true) erreurs.push('consentement');
// Anti-robot verifie cote serveur : champ piege vide et au moins 3 secondes de saisie.
if (s(b.site_web) || !(Number(b.duree_ms) >= 3000)) erreurs.push('robot');
// Limite de frequence : 20 demandes par heure au total, 3 par jour et par adresse.
// (Memorisee seulement quand le workflow est actif, pas en execution de test.)
if (!erreurs.length) {
  const memoire = $getWorkflowStaticData('global');
  const maintenant = Date.now();
  const envois = (memoire.envois || []).filter((e) => maintenant - e.t < 86400000);
  const heure = envois.filter((e) => maintenant - e.t < 3600000).length;
  const memeAdresse = envois.filter((e) => e.a === email.toLowerCase()).length;
  if (heure >= 20 || memeAdresse >= 3) erreurs.push('limite');
  else envois.push({ t: maintenant, a: email.toLowerCase() });
  memoire.envois = envois;
}
const recap = [`Nom : ${nom}`, `Prénom : ${prenom}`, `Téléphone : ${telephone}`, `E-mail : ${email}`, '', 'Message :', message].join('\n');
// L'accuse de reception ne recopie aucun texte saisi : il ne peut pas servir a envoyer du spam.
return [{ json: {
  ok: erreurs.length === 0,
  erreurs,
  to_eleveur: email,
  sujet_abattoir: `[Site] Contact - ${nom} ${prenom}`,
  texte_abattoir: recap,
  sujet_eleveur: 'Abattoir de Neuvy : nous avons bien reçu votre message',
  texte_eleveur: `Bonjour,\n\nNous avons bien reçu votre message. Nous vous rappelons sous 48 h ouvrées.\n\nAbattoir de Neuvy\nLe Fay, 79130 Neuvy-Bouin\nTél. : 05 49 63 51 30`
}}];
